scripts:
		$('.list-page-btn-wrap li').on('click', function(){
			$(this).addClass('active').siblings('li').removeClass('active');
		});

		// 当前需要渲染数据的海事局的栏目id
    	var channelId = '9c219298b27f460e995a99401b3ff6af';
		/**
		 * 加载数据
		 * @param pageNum
		 */
		function articleListRequest(pageNum) {
			$(".info-list-wrap").empty();
			$(".pages-pagina-wrap").empty();
			pageNum = pageNum || 1;
			//栏目文章列表页的渲染
			wapUtils.ajax(wapUtils.article.selectPageByChannelId, {
				channelId: channelId,
				pageNum: pageNum,
				count: 10
			}, wapUtils.methods.POST, wapUtils.dataTypes.JSON, function (data) {
				if (!wapUtils.isEmpty(data.list)) {
					$.each(data.list, function (index, item) {
						var liHtml = '<li class="info-list"><a href="/msacncms_wap/pages/content.jhtml?articleId={0}&channelId={1}"><p class="info-text">{2}</p><div class="info-status"><span class="time">{3}</span></div></a></li>';
						$(".info-list-wrap").append(liHtml.format(item.articleId, item.channelArticle.channelId, item.articleTitle, item.articlePublishTime.substring(0, 10)));
					});
					// 分页信息
					var pageContent = '<div class="btn first"><i class="iconfont" onclick="articleListRequest(1);">&#xe604;</i></div><div class="btn prev"><i class="iconfont" onclick="articleListRequest(' + data.prePage + ');">&#xe601;</i></div><ul>';
					$.each(data.navigatepageNums, function (index, item) {
						if (pageNum == item) {
							pageContent += '<li class="active">' + item + '</li>';
						} else {
							pageContent += '<li onclick="articleListRequest(' + item + ');">' + item + '</li>';
						}
					});
					pageContent += '</ul><div class="btn next" ><i class="iconfont" onclick="articleListRequest(' + data.nextPage + ');">&#xe600;</i></div><div class="btn last" ><i class="iconfont" onclick="articleListRequest(' + data.pages + ');">&#xe6b4;</i></div>';
					$(".pages-pagina-wrap").html(pageContent);
				}
			});
		}
		articleListRequest(1);

		/**
		 * 点击栏目执行的方法
		 * @param index 索引号
		 */
		function clickChannel(li) {
			channelId = $(li).data('id');
			if (channelId == '0') {
				channelId = '9c219298b27f460e995a99401b3ff6af';
			}
			// 执行数据渲染
			articleListRequest(1);
		}
